// Per-MODULE attribution of the eager JS bundle.
//
// `check-bundle-size.mjs` answers "how big is eager JS?". This answers "WHICH
// MODULES is it made of?", which is the question a headroom campaign actually
// needs: chunk-level totals hide whether a chunk is one deferrable feature or
// forty first-paint modules, and that distinction is what decides whether a
// lazy split is available at all.
//
// It exists as a committed script rather than a one-off because
// plans/BUNDLE_HEADROOM.md is meant to drive a multi-PR campaign: every slice
// has to state its MEASURED net eager delta, which means re-running this
// before and after. A number nobody else can regenerate cannot authorize
// work.
//
// ── WHAT THE NUMBERS ARE, AND ARE NOT ────────────────────────────────────
// Attribution is per source module, of MINIFIED generated bytes, derived from
// the sourcemap. It is not a promise of recoverable bytes: deferring a module
// frees its attributed bytes only if nothing else eager still pulls it, and a
// module that is split keeps whatever share stays on the eager side. Treat
// every figure here as an UPPER BOUND on what a split could recover, and
// measure the real delta with `check-bundle-size.mjs` before and after.
//
// The total is also a lower bound on the eager total: chunk boilerplate and
// runtime that no mapping segment covers is unattributed.
//
// Usage (from frontend/):
//   npx vite build --sourcemap && node scripts/profile-eager-bundle.mjs
//
// `--sourcemap` is required; without it there is nothing to attribute. The
// normal `npm run build` does not emit maps, so remember to rebuild without
// them afterwards if the output tree matters.

import { readFileSync, existsSync, statSync } from "node:fs";
import { readdir } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

// fileURLToPath, never `new URL(...).pathname`: on Windows the latter keeps
// the drive letter behind a leading slash (see vite.config.ts's note).
const here = dirname(fileURLToPath(import.meta.url));
const distDir = resolve(here, "..", "..", "src", "quantized", "web");
const repoRoot = resolve(here, "..", "..");

const B64 = new Map(
  [..."ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"].map((c, i) => [c, i]),
);

/** Decode one VLQ segment into its signed fields. */
function decodeSegment(seg) {
  const out = [];
  let shift = 0;
  let acc = 0;
  for (const ch of seg) {
    const d = B64.get(ch);
    if (d === undefined) return out; // malformed — skip the rest of the segment
    acc |= (d & 31) << shift;
    if (d & 32) {
      shift += 5;
    } else {
      out.push((acc >> 1) * (acc & 1 ? -1 : 1));
      shift = 0;
      acc = 0;
    }
  }
  return out;
}

/** The chunks the browser loads before any user interaction: the entry script
 *  plus every `modulepreload`. Identical to check-bundle-size.mjs's rule, so
 *  the two tools always agree about what "eager" means. */
function eagerChunkNames() {
  const html = readFileSync(join(distDir, "index.html"), "utf8");
  const refs = [
    ...html.matchAll(/<script[^>]+type="module"[^>]+src="([^"]+\.js)"/g),
    ...html.matchAll(/<link[^>]+rel="modulepreload"[^>]+href="([^"]+\.js)"/g),
  ].map((m) => m[1].replace(/^\//, ""));
  return new Set(refs.map((r) => r.split("/").pop()));
}

/** Bytes of generated output attributed to each source module. A segment owns
 *  the generated text from its own column up to the next segment's column (or
 *  end of line). */
function attribute(mapPath, jsPath, into) {
  const map = JSON.parse(readFileSync(mapPath, "utf8"));
  const lines = readFileSync(jsPath, "utf8").split("\n");
  let srcIndex = 0;
  map.mappings.split(";").forEach((lineMappings, lineNo) => {
    let col = 0;
    const segs = [];
    for (const seg of lineMappings.split(",")) {
      if (!seg) continue;
      const v = decodeSegment(seg);
      if (v.length === 0) continue;
      col += v[0];
      if (v.length >= 4) {
        srcIndex += v[1];
        segs.push([col, srcIndex]);
      }
    }
    const lineLen = lineNo < lines.length ? lines[lineNo].length : 0;
    segs.forEach(([c, si], i) => {
      const end = i + 1 < segs.length ? segs[i + 1][0] : lineLen;
      const src = map.sources[si];
      if (src !== undefined) into.set(src, (into.get(src) ?? 0) + Math.max(0, end - c));
    });
  });
}

const assets = join(distDir, "assets");
if (!existsSync(assets)) {
  console.error("profile-eager-bundle: no build output — run `npx vite build --sourcemap` first.");
  process.exit(1);
}

const eager = eagerChunkNames();
const maps = (await readdir(assets)).filter((f) => f.endsWith(".js.map") && eager.has(f.slice(0, -4)));
if (maps.length === 0) {
  console.error(
    "profile-eager-bundle: found no sourcemaps for eager chunks.\n" +
      "The build must be run WITH --sourcemap (`npx vite build --sourcemap`).",
  );
  process.exit(1);
}

const bytes = new Map();
for (const m of maps) attribute(join(assets, m), join(assets, m.slice(0, -4)), bytes);

const total = [...bytes.values()].reduce((a, b) => a + b, 0);
const eagerOnDisk = [...eager].reduce(
  (sum, f) => sum + (existsSync(join(assets, f)) ? statSync(join(assets, f)).size : 0),
  0,
);

const rows = [...bytes.entries()]
  .map(([src, b]) => [b, src.replace(/^(\.\.\/)+/, "").replace(`${repoRoot}/`, "")])
  .sort((a, b) => b[0] - a[0]);

const vendor = rows.filter(([, s]) => s.includes("node_modules")).reduce((a, [b]) => a + b, 0);

console.log(`eager chunks:        ${eager.size}`);
console.log(`bytes on disk:       ${eagerOnDisk.toLocaleString()}`);
console.log(`attributed:          ${total.toLocaleString()}  (rest is chunk boilerplate/runtime)`);
console.log(`  of which vendor:   ${vendor.toLocaleString()} (${((vendor / total) * 100).toFixed(1)}%)`);
console.log(`\n${"bundled B".padStart(10)}  module   [UPPER BOUND on what deferring could recover]`);
for (const [b, src] of rows.slice(0, Number(process.env.TOP ?? 25))) {
  console.log(`${b.toLocaleString().padStart(10)}  ${src}`);
}
